import z3,networkx as nx,itertools,pickle,os
m=7; P=5
E=[[z3.Bool(f'e{i}_{j}') for j in range(P)] for i in range(P)]
s=z3.Solver();s.add(E[0][4],z3.Not(E[4][0]),z3.Not(E[0][0]),z3.Not(E[4][4]))
def lit(a,b):
 i,x=divmod(a,P);j,y=divmod(b,P)
 if i==j:return z3.BoolVal(abs(x-y)==1)
 return E[x][y] if i<j else E[y][x]
N=m*P
edges={(a,b):lit(a,b) for a in range(N) for b in range(a+1,N)}
def expr(a,b):return edges[min(a,b),max(a,b)]
def no_cycle(G,k):
 # DFS cycles finding one
 for v in G:
  stack=[(v,[v])]
  while stack:
   u,path=stack.pop()
   if len(path)==k:
    if G.has_edge(u,v):return path
   else:
    for w in G[u]:
     if w>v and w not in path:stack.append((w,path+[w]))
 return None
cnt=0
while s.check()==z3.sat:
 model=s.model();G=nx.Graph();G.add_nodes_from(range(N));G.add_edges_from((a,b) for (a,b),e in edges.items() if z3.is_true(model.eval(e,model_completion=True)))
 cyc=no_cycle(G,3) or no_cycle(G,5)
 if cyc:
  ls=[expr(a,b) for a,b in zip(cyc,cyc[1:]+cyc[:1])];s.add(z3.Or(*[z3.Not(e) for e in ls]));cnt+=1;continue
 F=nx.Graph();F.add_nodes_from(G);witness={}
 for a in G:
  for b in G[a]:
   if a<b:F.add_edge(a,b);witness[a,b]=[expr(a,b)]
  for b in G[a]:
   for c in G[b]:
    for d in G[c]:
     if a<d:
      F.add_edge(a,d);witness[a,d]=[expr(a,b),expr(b,c),expr(c,d)]
 cl=next((x[:5] for x in nx.find_cliques(F) if len(x)>=5),None)
 if cl:
  ls=sum((witness[min(a,b),max(a,b)] for a,b in itertools.combinations(cl,2)),[])
  s.add(z3.Or(*[z3.Not(e) for e in ls]));cnt+=1;continue
 print('COUNTEREXAMPLE',cnt,'edges',G.number_of_edges(),'clique',nx.graph_clique_number(F))
 print([[int(z3.is_true(model.eval(E[i][j]))) for j in range(P)] for i in range(P)])
 break
else: print('UNSAT',cnt)

