m=12;n=5*m
N=[set() for _ in range(n)]
for i in range(5):
 for a in range(m):
  for b in range(a+1,m):
   u=i*m+a;v=((i+1)%5)*m+b;N[u].add(v);N[v].add(u)
def good(u,v):
 if N[u]&N[v]:return False
 U=set().union(*(N[x] for x in N[u]));V=set().union(*(N[x] for x in N[v]))
 return not U&V
def coltest(q):
 F=set()
 for a in range(n):
  for b in N[a]:
   F.add(tuple(sorted((a,b))))
   for c in N[b]:
    for d in N[c]:
     assert a!=d
     F.add(tuple(sorted((a,d))))
 cs=[z3.Int(f'c{i}') for i in range(n)];s=z3.Solver();s.set(timeout=10000)
 s.add(*[z3.And(c>=0,c<q) for c in cs]);s.add(*[cs[a]!=cs[b] for a,b in F]);s.add(cs[0]==0)
 return s.check(),len(F)
