for step in range(200000):
 a=random.randrange(n);b=random.choice(tuple(N[a]));c=random.randrange(n);d=random.choice(tuple(N[c]))
 if len({a,b,c,d})<4 or c in N[a] or d in N[b]:continue
 N[a].remove(b);N[b].remove(a);N[c].remove(d);N[d].remove(c)
 if good(a,c):
  N[a].add(c);N[c].add(a)
  if good(b,d):
   N[b].add(d);N[d].add(b);acc+=1
   if (a//m-c//m)%5 not in [1,4] or (b//m-d//m)%5 not in [1,4]:bad+=1
   continue
  N[a].remove(c);N[c].remove(a)
 N[a].add(b);N[b].add(a);N[c].add(d);N[d].add(c)
print('seconds',time.time()-start,'accepted',acc,'wrongtype',bad,'test5',coltest(5))
